python3 - <<'PY'
from fastapi.sse import ServerSentEvent

def test_sse_validation():
    # 1. Valid input
    try:
        ServerSentEvent(id="123", event="test", data="valid")
        print("Test 1 (Valid) passed.")
    except Exception as e:
        print(f"Test 1 (Valid) FAILED unexpectedly: {e}")

    # 2. Invalid id with newline
    try:
        ServerSentEvent(id="123\n456", data="test")
        print("Test 2 (ID Newline) FAILED: Expected ValueError, got success.")
    except ValueError as e:
        if "SSE field must not contain newline characters" in str(e):
            print("Test 2 (ID Newline) passed.")
        else:
            print(f"Test 2 (ID Newline) FAILED: Wrong error message: {e}")
    except Exception as e:
        print(f"Test 2 (ID Newline) FAILED: Wrong exception type: {e}")

    # 3. Invalid id with null byte
    try:
        ServerSentEvent(id="123\0456", data="test")
        print("Test 3 (ID Null Byte) FAILED: Expected ValueError, got success.")
    except ValueError as e:
        if "SSE field must not contain null characters" in str(e):
            print("Test 3 (ID Null Byte) passed.")
        else:
            print(f"Test 3 (ID Null Byte) FAILED: Wrong error message: {e}")
    except Exception as e:
        print(f"Test 3 (ID Null Byte) FAILED: Wrong exception type: {e}")

    # 4. Invalid event with newline
    try:
        ServerSentEvent(event="test\r\n", data="test")
        print("Test 4 (Event Newline) FAILED: Expected ValueError, got success.")
    except ValueError as e:
        if "SSE field must not contain newline characters" in str(e):
            print("Test 4 (Event Newline) passed.")
        else:
            print(f"Test 4 (Event Newline) FAILED: Wrong error message: {e}")
    except Exception as e:
        print(f"Test 4 (Event Newline) FAILED: Wrong exception type: {e}")

    # 5. Invalid event with null byte
    try:
        ServerSentEvent(event="test\0", data="test")
        print("Test 5 (Event Null Byte) FAILED: Expected ValueError, got success.")
    except ValueError as e:
        if "SSE field must not contain null characters" in str(e):
            print("Test 5 (Event Null Byte) passed.")
        else:
            print(f"Test 5 (Event Null Byte) FAILED: Wrong error message: {e}")
    except Exception as e:
        print(f"Test 5 (Event Null Byte) FAILED: Wrong exception type: {e}")

test_sse_validation()
